  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turned atomic spectroscopy into an exceptionally precise measurement platform, advancing tests of fundamental physics as well as timekeeping.",
        "attribution": "Katori and Ye are central, distinct contributors to the lattice-clock concept and its experimental realization.",
        "maturity": "The method has been demonstrated and refined across laboratories, with clock performance and applications continuing to improve.",
        "uncertainties": [
          "The case depends on whether the committee views the clock as a sufficiently fundamental discovery rather than a major precision instrument."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided a controllable route to quantum logic and simulation, making quantum information experimentally accessible and enabling precise control of individual quantum systems.",
        "attribution": "Cirac and Zoller established key theoretical foundations; Blatt led decisive experimental demonstrations. Their roles are complementary.",
        "maturity": "Quantum gates, entanglement and small-scale algorithms have been repeatedly demonstrated, although scalable fault-tolerant computing remains unfinished.",
        "uncertainties": [
          "The boundary between the trapped-ion contribution and the broader development of quantum computing is difficult to draw."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution connected foundational quantum principles to a new form of secure communication and helped establish quantum information as an experimental field.",
        "attribution": "Bennett and Brassard developed a landmark protocol, while Ekert introduced a distinct entanglement-based approach. Jian-Wei Pan's experimental contributions are important, but the nominated work spans many later teams.",
        "maturity": "The principles have been tested extensively and deployed in limited settings; practical systems still face engineering and security constraints.",
        "uncertainties": [
          "The field's broad history makes it challenging to assign a compact and fair share of credit."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made matter waves into exceptionally sensitive probes, opening precision measurements of acceleration, rotation and gravity.",
        "attribution": "Bordé's early atom-optics work, Pritchard's foundational experiments and Kasevich's advanced interferometers represent important parts of the development.",
        "maturity": "The technique is well established in laboratory instruments and continues to improve; its range of precision applications is demonstrated.",
        "uncertainties": [
          "The discovery is distributed across a long experimental history, so the contribution boundaries need careful treatment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold Fermi gases enabled controlled studies of strongly interacting matter and the BEC–BCS crossover, giving many-body physics a tunable experimental system.",
        "attribution": "These researchers led complementary experiments across different platforms and regimes; the broader field also relies on substantial contributions from other groups.",
        "maturity": "The crossover and universal properties have been measured and reproduced over many years, though important questions about real materials and transport remain.",
        "uncertainties": [
          "It is difficult to separate the nominated experimental achievements from the wider international effort that established the field."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation created a flexible laboratory for studying quantum many-body systems and phases that are difficult to access in materials.",
        "attribution": "Bloch, Greiner and Esslinger made influential experimental demonstrations on complementary systems; Cirac and Zoller supplied important theoretical foundations.",
        "maturity": "The platform has produced many robust results, but its predictive reach for problems beyond the simulator remains an active question.",
        "uncertainties": [
          "The line between quantum simulation as a discovery and as a versatile experimental method is not yet settled."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "David Huang",
        "Eric A. Swanson",
        "James G. Fujimoto"
      ],
      "assessment": {
        "nobel_worthiness": "Optical coherence tomography is a major measurement innovation that made high-resolution, non-invasive imaging practical and transformed ophthalmic diagnosis.",
        "attribution": "Fujimoto, Swanson and Huang are closely associated with the early development and clinical translation of the method.",
        "maturity": "The technique is widely used and its physical basis and clinical value are well established.",
        "uncertainties": [
          "The award case rests partly on how the committee weighs a biomedical imaging method against discoveries that primarily advance fundamental physics."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube's detection of high-energy astrophysical neutrinos opened a new observational window on energetic cosmic sources and established neutrino astronomy.",
        "attribution": "Halzen was central to developing and realizing the detector, but the result is the work of a large international collaboration.",
        "maturity": "The astrophysical signal is established and follow-up observations have accumulated, while identifying the dominant source populations remains ongoing.",
        "uncertainties": [
          "Credit for a collaboration-scale discovery cannot be fully represented by the single proposed laureate.",
          "The astrophysical interpretation and source identification are not yet complete."
        ]
      }
    }
  ]
}
